function(req, res) {
    let uri = url.parse(req.url).pathname;
    let filename;

    if (uri === "/test/") {
        uri = "/test/index.html";
    }

    filename = path.join(process.cwd(), uri);

    domain.on("error", function() {
        res.writeHead(404, {
            "Content-Type": "text/plain"
        });

        res.end("404 Not Found\n");
    });

    domain.run(function() {
        const mimeType = mimeTypes[path.extname(filename).split(".")[1]] || "text/plain";

        res.writeHead(200, {
            "Content-Type": mimeType
        });

        fs.createReadStream(filename).pipe(res);
    });
}

function() {
    const self = this;
    const httpForwardedCount = parseInt(process.env["HTTP_FORWARDED_COUNT"]) || 0;

    if (httpForwardedCount === 0)
        return self.socket.remoteAddress;

    let forwardedFor = self.socket.headers["x-forwarded-for"];

    if (!isString(forwardedFor))
        return null;

    forwardedFor = forwardedFor.trim().split(/\s*,\s*/);

    if (httpForwardedCount < 0 || httpForwardedCount > forwardedFor.length)
        return null;

    return forwardedFor[forwardedFor.length - httpForwardedCount];
}

function() {
    const self = this;
    const httpForwardedCount = parseInt(process.env["HTTP_FORWARDED_COUNT"]) || 0;

    if (httpForwardedCount === 0)
        return self.socket.remoteAddress;

    let forwardedFor = self.socket.headers["x-forwarded-for"];

    if (!isString(forwardedFor))
        return null;

    forwardedFor = forwardedFor.split(",");

    if (httpForwardedCount < 0 || httpForwardedCount !== forwardedFor.length)
        return null;

    forwardedFor = forwardedFor.map(ip => ip.trim());
    return forwardedFor[forwardedFor.length - httpForwardedCount];
}

(function(root) {
    "use strict";
    const block = {
        newline: /^\n+/,
        code: /^( {4}[^\n]+\n*)+/,
        fences: noop,
        hr: /^ {0,3}((?:- *){3,}|(?:_ *){3,}|(?:\* *){3,})(?:\n+|$)/,
        heading: /^ *(#{1,6}) *([^\n]+?) *#* *(?:\n+|$)/,
        nptable: noop,
        blockquote: /^( {0,3}> ?(paragraph|[^\n]*)(?:\n|$))+/,
        list: /^( *)(bull) [\s\S]+?(?:hr|def|\n{2,}(?! )(?!\1bull )\n*|\s*$)/,
        html: /^ *(?:comment *(?:\n|\s*$)|closed *(?:\n{2,}|\s*$)|closing *(?:\n{2,}|\s*$))/,
        def: /^ {0,3}\[(label)\]: *\n? *<?([^\s>]+)>?(?:(?: +\n? *| *\n *)(title))? *(?:\n+|$)/,
        table: noop,
        lheading: /^([^\n]+)\n *(=|-){2,} *(?:\n+|$)/,
        paragraph: /^([^\n]+(?:\n?(?!hr|heading|lheading| {0,3}>|tag)[^\n]+)+)/,
        text: /^[^\n]+/
    };

    block._label = /(?:\\[\[\]]|[^\[\]])+/;
    block._title = /(?:"(?:\\"|[^"]|"[^"\n]*")*"|'\n?(?:[^'\n]+\n?)*'|\([^()]*\))/;
    block.def = edit(block.def).replace("label", block._label).replace("title", block._title).getRegex();
    block.bullet = /(?:[*+-]|\d+\.)/;
    block.item = /^( *)(bull) [^\n]*(?:\n(?!\1bull )[^\n]*)*/;
    block.item = edit(block.item, "gm").replace(/bull/g, block.bullet).getRegex();
    block.list = edit(block.list).replace(/bull/g, block.bullet).replace("hr", "\\n+(?=\\1?(?:(?:- *){3,}|(?:_ *){3,}|(?:\\* *){3,})(?:\\n+|$))").replace("def", "\\n+(?=" + block.def.source + ")").getRegex();
    block._tag = "(?!(?:" + "a|em|strong|small|s|cite|q|dfn|abbr|data|time|code" + "|var|samp|kbd|sub|sup|i|b|u|mark|ruby|rt|rp|bdi|bdo" + "|span|br|wbr|ins|del|img)\\b)\\w+(?!:|[^\\w\\s@]*@)\\b";
    block.html = edit(block.html).replace("comment", /<!--[\s\S]*?-->/).replace("closed", /<(tag)[\s\S]+?<\/\1>/).replace("closing", /<tag(?:"[^"]*"|'[^']*'|\s[^'"\/>]*)*?\/?>/).replace(/tag/g, block._tag).getRegex();
    block.paragraph = edit(block.paragraph).replace("hr", block.hr).replace("heading", block.heading).replace("lheading", block.lheading).replace("tag", "<" + block._tag).getRegex();
    block.blockquote = edit(block.blockquote).replace("paragraph", block.paragraph).getRegex();
    block.normal = merge({}, block);

    block.gfm = merge({}, block.normal, {
        fences: /^ *(`{3,}|~{3,})[ \.]*(\S+)? *\n([\s\S]*?)\n? *\1 *(?:\n+|$)/,
        paragraph: /^/,
        heading: /^ *(#{1,6}) +([^\n]+?) *#* *(?:\n+|$)/
    });

    block.gfm.paragraph = edit(block.paragraph).replace(
        "(?!",
        "(?!" + block.gfm.fences.source.replace("\\1", "\\2") + "|" + block.list.source.replace("\\1", "\\3") + "|"
    ).getRegex();

    block.tables = merge({}, block.gfm, {
        nptable: /^ *(\S.*\|.*)\n *([-:]+ *\|[-| :]*)\n((?:.*\|.*(?:\n|$))*)\n*/,
        table: /^ *\|(.+)\n *\|( *[-:]+[-| :]*)\n((?: *\|.*(?:\n|$))*)\n*/
    });

    function Lexer(options) {
        this.tokens = [];
        this.tokens.links = {};
        this.options = options || marked.defaults;
        this.rules = block.normal;

        if (this.options.gfm) {
            if (this.options.tables) {
                this.rules = block.tables;
            } else {
                this.rules = block.gfm;
            }
        }
    }

    Lexer.rules = block;

    Lexer.lex = function(src, options) {
        const lexer = new Lexer(options);
        return lexer.lex(src);
    };

    Lexer.prototype.lex = function(src) {
        src = src.replace(/\r\n|\r/g, "\n").replace(/\t/g, "    ").replace(/\u00a0/g, " ").replace(/\u2424/g, "\n");
        return this.token(src, true);
    };

    Lexer.prototype.token = function(src, top) {
        src = src.replace(/^ +$/gm, "");
        let next;
        let loose;
        let cap;
        let bull;
        let b;
        let item;
        let space;
        let i;
        let tag;
        let l;

        while (src) {
            if ((cap = this.rules.newline.exec(src))) {
                src = src.substring(cap[0].length);

                if (cap[0].length > 1) {
                    this.tokens.push({
                        type: "space"
                    });
                }
            }

            if ((cap = this.rules.code.exec(src))) {
                src = src.substring(cap[0].length);
                cap = cap[0].replace(/^ {4}/gm, "");

                this.tokens.push({
                    type: "code",
                    text: !this.options.pedantic ? cap.replace(/\n+$/, "") : cap
                });

                continue;
            }

            if ((cap = this.rules.fences.exec(src))) {
                src = src.substring(cap[0].length);

                this.tokens.push({
                    type: "code",
                    lang: cap[2],
                    text: cap[3] || ""
                });

                continue;
            }

            if ((cap = this.rules.heading.exec(src))) {
                src = src.substring(cap[0].length);

                this.tokens.push({
                    type: "heading",
                    depth: cap[1].length,
                    text: cap[2]
                });

                continue;
            }

            if (top && (cap = this.rules.nptable.exec(src))) {
                src = src.substring(cap[0].length);

                item = {
                    type: "table",
                    header: cap[1].replace(/^ *| *\| *$/g, "").split(/ *\| */),
                    align: cap[2].replace(/^ *|\| *$/g, "").split(/ *\| */),
                    cells: cap[3].replace(/\n$/, "").split("\n")
                };

                for (i = 0; i < item.align.length; i++) {
                    if (/^ *-+: *$/.test(item.align[i])) {
                        item.align[i] = "right";
                    } else if (/^ *:-+: *$/.test(item.align[i])) {
                        item.align[i] = "center";
                    } else if (/^ *:-+ *$/.test(item.align[i])) {
                        item.align[i] = "left";
                    } else {
                        item.align[i] = null;
                    }
                }

                for (i = 0; i < item.cells.length; i++) {
                    item.cells[i] = item.cells[i].split(/ *\| */);
                }

                this.tokens.push(item);
                continue;
            }

            if ((cap = this.rules.hr.exec(src))) {
                src = src.substring(cap[0].length);

                this.tokens.push({
                    type: "hr"
                });

                continue;
            }

            if ((cap = this.rules.blockquote.exec(src))) {
                src = src.substring(cap[0].length);

                this.tokens.push({
                    type: "blockquote_start"
                });

                cap = cap[0].replace(/^ *> ?/gm, "");
                this.token(cap, top);

                this.tokens.push({
                    type: "blockquote_end"
                });

                continue;
            }

            if ((cap = this.rules.list.exec(src))) {
                src = src.substring(cap[0].length);
                bull = cap[2];

                this.tokens.push({
                    type: "list_start",
                    ordered: bull.length > 1
                });

                cap = cap[0].match(this.rules.item);
                next = false;
                l = cap.length;
                i = 0;

                for (; i < l; i++) {
                    item = cap[i];
                    space = item.length;
                    item = item.replace(/^ *([*+-]|\d+\.) +/, "");

                    if (~item.indexOf("\n ")) {
                        space -= item.length;
                        item = !this.options.pedantic ? item.replace(new RegExp("^ {1," + space + "}", "gm"), "") : item.replace(/^ {1,4}/gm, "");
                    }

                    if (this.options.smartLists && i !== l - 1) {
                        b = block.bullet.exec(cap[i + 1])[0];

                        if (bull !== b && !(bull.length > 1 && b.length > 1)) {
                            src = cap.slice(i + 1).join("\n") + src;
                            i = l - 1;
                        }
                    }

                    loose = next || /\n\n(?!\s*$)/.test(item);

                    if (i !== l - 1) {
                        next = item.charAt(item.length - 1) === "\n";

                        if (!loose)
                            loose = next;
                    }

                    this.tokens.push({
                        type: loose ? "loose_item_start" : "list_item_start"
                    });

                    this.token(item, false);

                    this.tokens.push({
                        type: "list_item_end"
                    });
                }

                this.tokens.push({
                    type: "list_end"
                });

                continue;
            }

            if ((cap = this.rules.html.exec(src))) {
                src = src.substring(cap[0].length);

                this.tokens.push({
                    type: this.options.sanitize ? "paragraph" : "html",
                    pre: !this.options.sanitizer && (cap[1] === "pre" || cap[1] === "script" || cap[1] === "style"),
                    text: cap[0]
                });

                continue;
            }

            if (top && (cap = this.rules.def.exec(src))) {
                src = src.substring(cap[0].length);

                if (cap[3])
                    cap[3] = cap[3].substring(1, cap[3].length - 1);

                tag = cap[1].toLowerCase();

                if (!this.tokens.links[tag]) {
                    this.tokens.links[tag] = {
                        href: cap[2],
                        title: cap[3]
                    };
                }

                continue;
            }

            if (top && (cap = this.rules.table.exec(src))) {
                src = src.substring(cap[0].length);

                item = {
                    type: "table",
                    header: cap[1].replace(/^ *| *\| *$/g, "").split(/ *\| */),
                    align: cap[2].replace(/^ *|\| *$/g, "").split(/ *\| */),
                    cells: cap[3].replace(/(?: *\| *)?\n$/, "").split("\n")
                };

                for (i = 0; i < item.align.length; i++) {
                    if (/^ *-+: *$/.test(item.align[i])) {
                        item.align[i] = "right";
                    } else if (/^ *:-+: *$/.test(item.align[i])) {
                        item.align[i] = "center";
                    } else if (/^ *:-+ *$/.test(item.align[i])) {
                        item.align[i] = "left";
                    } else {
                        item.align[i] = null;
                    }
                }

                for (i = 0; i < item.cells.length; i++) {
                    item.cells[i] = item.cells[i].replace(/^ *\| *| *\| *$/g, "").split(/ *\| */);
                }

                this.tokens.push(item);
                continue;
            }

            if ((cap = this.rules.lheading.exec(src))) {
                src = src.substring(cap[0].length);

                this.tokens.push({
                    type: "heading",
                    depth: cap[2] === "=" ? 1 : 2,
                    text: cap[1]
                });

                continue;
            }

            if (top && (cap = this.rules.paragraph.exec(src))) {
                src = src.substring(cap[0].length);

                this.tokens.push({
                    type: "paragraph",
                    text: cap[1].charAt(cap[1].length - 1) === "\n" ? cap[1].slice(0, -1) : cap[1]
                });

                continue;
            }

            if ((cap = this.rules.text.exec(src))) {
                src = src.substring(cap[0].length);

                this.tokens.push({
                    type: "text",
                    text: cap[0]
                });

                continue;
            }

            if (src) {
                throw new Error("Infinite loop on byte: " + src.charCodeAt(0));
            }
        }

        return this.tokens;
    };

    const inline = {
        escape: /^\\([\\`*{}\[\]()#+\-.!_>])/,
        autolink: /^<(scheme:[^\s\x00-\x1f<>]*|email)>/,
        url: noop,
        tag: /^<!--[\s\S]*?-->|^<\/?[a-zA-Z0-9\-]+(?:"[^"]*"|'[^']*'|\s[^<'">\/]*)*?\/?>/,
        link: /^!?\[(inside)\]\(href\)/,
        reflink: /^!?\[(inside)\]\s*\[([^\]]*)\]/,
        nolink: /^!?\[((?:\[[^\]]*\]|\\[\[\]]|[^\[\]])*)\]/,
        strong: /^__([\s\S]+?)__(?!_)|^\*\*([\s\S]+?)\*\*(?!\*)/,
        em: /^_([^\s_](?:[^_]|__)+?[^\s_])_\b|^\*((?:\*\*|[^*])+?)\*(?!\*)/,
        code: /^(`+)\s*([\s\S]*?[^`]?)\s*\1(?!`)/,
        br: /^ {2,}\n(?!\s*$)/,
        del: noop,
        text: /^[\s\S]+?(?=[\\<!\[`*]|\b_| {2,}\n|$)/
    };

    inline._scheme = /[a-zA-Z][a-zA-Z0-9+.-]{1,31}/;
    inline._email = /[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+(@)[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+(?![-_])/;
    inline.autolink = edit(inline.autolink).replace("scheme", inline._scheme).replace("email", inline._email).getRegex();
    inline._inside = /(?:\[[^\]]*\]|\\[\[\]]|[^\[\]]|\](?=[^\[]*\]))*/;
    inline._href = /\s*<?([\s\S]*?)>?(?:\s+['"]([\s\S]*?)['"])?\s*/;
    inline.link = edit(inline.link).replace("inside", inline._inside).replace("href", inline._href).getRegex();
    inline.reflink = edit(inline.reflink).replace("inside", inline._inside).getRegex();
    inline.normal = merge({}, inline);

    inline.pedantic = merge({}, inline.normal, {
        strong: /^__(?=\S)([\s\S]*?\S)__(?!_)|^\*\*(?=\S)([\s\S]*?\S)\*\*(?!\*)/,
        em: /^_(?=\S)([\s\S]*?\S)_(?!_)|^\*(?=\S)([\s\S]*?\S)\*(?!\*)/
    });

    inline.gfm = merge({}, inline.normal, {
        escape: edit(inline.escape).replace("])", "~|])").getRegex(),
        url: edit(/^((?:ftp|https?):\/\/|www\.)(?:[a-zA-Z0-9\-]+\.?)+[^\s<]*|^email/).replace("email", inline._email).getRegex(),
        _backpedal: /(?:[^?!.,:;*_~()&]+|\([^)]*\)|&(?![a-zA-Z0-9]+;$)|[?!.,:;*_~)]+(?!$))+/,
        del: /^~~(?=\S)([\s\S]*?\S)~~/,
        text: edit(inline.text).replace("]|", "~]|").replace("|", "|https?://|ftp://|www\\.|[a-zA-Z0-9.!#$%&'*+/=?^_`{\\|}~-]+@|").getRegex()
    });

    inline.breaks = merge({}, inline.gfm, {
        br: edit(inline.br).replace("{2,}", "*").getRegex(),
        text: edit(inline.gfm.text).replace("{2,}", "*").getRegex()
    });

    function InlineLexer(links, options) {
        this.options = options || marked.defaults;
        this.links = links;
        this.rules = inline.normal;
        this.renderer = this.options.renderer || new Renderer();
        this.renderer.options = this.options;

        if (!this.links) {
            throw new Error("Tokens array requires a `links` property.");
        }

        if (this.options.gfm) {
            if (this.options.breaks) {
                this.rules = inline.breaks;
            } else {
                this.rules = inline.gfm;
            }
        } else if (this.options.pedantic) {
            this.rules = inline.pedantic;
        }
    }

    InlineLexer.rules = inline;

    InlineLexer.output = function(src, links, options) {
        const inline = new InlineLexer(links, options);
        return inline.output(src);
    };

    InlineLexer.prototype.output = function(src) {
        let out = "";
        let link;
        let text;
        let href;
        let cap;

        while (src) {
            if ((cap = this.rules.escape.exec(src))) {
                src = src.substring(cap[0].length);
                out += cap[1];
                continue;
            }

            if ((cap = this.rules.autolink.exec(src))) {
                src = src.substring(cap[0].length);

                if (cap[2] === "@") {
                    text = escape(this.mangle(cap[1]));
                    href = "mailto:" + text;
                } else {
                    text = escape(cap[1]);
                    href = text;
                }

                out += this.renderer.link(href, null, text);
                continue;
            }

            if (!this.inLink && (cap = this.rules.url.exec(src))) {
                cap[0] = this.rules._backpedal.exec(cap[0])[0];
                src = src.substring(cap[0].length);

                if (cap[2] === "@") {
                    text = escape(cap[0]);
                    href = "mailto:" + text;
                } else {
                    text = escape(cap[0]);

                    if (cap[1] === "www.") {
                        href = "http://" + text;
                    } else {
                        href = text;
                    }
                }

                out += this.renderer.link(href, null, text);
                continue;
            }

            if ((cap = this.rules.tag.exec(src))) {
                if (!this.inLink && /^<a /i.test(cap[0])) {
                    this.inLink = true;
                } else if (this.inLink && /^<\/a>/i.test(cap[0])) {
                    this.inLink = false;
                }

                src = src.substring(cap[0].length);
                out += this.options.sanitize ? this.options.sanitizer ? this.options.sanitizer(cap[0]) : escape(cap[0]) : cap[0];
                continue;
            }

            if ((cap = this.rules.link.exec(src))) {
                src = src.substring(cap[0].length);
                this.inLink = true;

                out += this.outputLink(cap, {
                    href: cap[2],
                    title: cap[3]
                });

                this.inLink = false;
                continue;
            }

            if ((cap = this.rules.reflink.exec(src)) || (cap = this.rules.nolink.exec(src))) {
                src = src.substring(cap[0].length);
                link = (cap[2] || cap[1]).replace(/\s+/g, " ");
                link = this.links[link.toLowerCase()];

                if (!link || !link.href) {
                    out += cap[0].charAt(0);
                    src = cap[0].substring(1) + src;
                    continue;
                }

                this.inLink = true;
                out += this.outputLink(cap, link);
                this.inLink = false;
                continue;
            }

            if ((cap = this.rules.strong.exec(src))) {
                src = src.substring(cap[0].length);
                out += this.renderer.strong(this.output(cap[2] || cap[1]));
                continue;
            }

            if ((cap = this.rules.em.exec(src))) {
                src = src.substring(cap[0].length);
                out += this.renderer.em(this.output(cap[2] || cap[1]));
                continue;
            }

            if ((cap = this.rules.code.exec(src))) {
                src = src.substring(cap[0].length);
                out += this.renderer.codespan(escape(cap[2].trim(), true));
                continue;
            }

            if ((cap = this.rules.br.exec(src))) {
                src = src.substring(cap[0].length);
                out += this.renderer.br();
                continue;
            }

            if ((cap = this.rules.del.exec(src))) {
                src = src.substring(cap[0].length);
                out += this.renderer.del(this.output(cap[1]));
                continue;
            }

            if ((cap = this.rules.text.exec(src))) {
                src = src.substring(cap[0].length);
                out += this.renderer.text(escape(this.smartypants(cap[0])));
                continue;
            }

            if (src) {
                throw new Error("Infinite loop on byte: " + src.charCodeAt(0));
            }
        }

        return out;
    };

    InlineLexer.prototype.outputLink = function(cap, link) {
        const href = escape(link.href);
        const title = link.title ? escape(link.title) : null;
        return cap[0].charAt(0) !== "!" ? this.renderer.link(href, title, this.output(cap[1])) : this.renderer.image(href, title, escape(cap[1]));
    };

    InlineLexer.prototype.smartypants = function(text) {
        if (!this.options.smartypants)
            return text;

        return (text.replace(/---/g, "—").replace(/--/g, "–").replace(/(^|[-\u2014/(\[{"\s])'/g, "$1‘").replace(/'/g, "’").replace(/(^|[-\u2014/(\[{\u2018\s])"/g, "$1“").replace(/"/g, "”").replace(/\.{3}/g, "…"));
    };

    InlineLexer.prototype.mangle = function(text) {
        if (!this.options.mangle)
            return text;

        let out = "";
        const l = text.length;
        let i = 0;
        let ch;

        for (; i < l; i++) {
            ch = text.charCodeAt(i);

            if (Math.random() > 0.5) {
                ch = "x" + ch.toString(16);
            }

            out += "&#" + ch + ";";
        }

        return out;
    };

    function Renderer(options) {
        this.options = options || {};
    }

    Renderer.prototype.code = function(code, lang, escaped) {
        if (this.options.highlight) {
            const out = this.options.highlight(code, lang);

            if (out != null && out !== code) {
                escaped = true;
                code = out;
            }
        }

        if (!lang) {
            return "<pre><code>" + (escaped ? code : escape(code, true)) + "\n</code></pre>";
        }

        return ("<pre><code class=\"" + this.options.langPrefix + escape(lang, true) + "\">" + (escaped ? code : escape(code, true)) + "\n</code></pre>\n");
    };

    Renderer.prototype.blockquote = function(quote) {
        return "<blockquote>\n" + quote + "</blockquote>\n";
    };

    Renderer.prototype.html = function(html) {
        return html;
    };

    Renderer.prototype.heading = function(text, level, raw) {
        return ("<h" + level + " id=\"" + this.options.headerPrefix + raw.toLowerCase().replace(/[^\w]+/g, "-") + "\">" + text + "</h" + level + ">\n");
    };

    Renderer.prototype.hr = function() {
        return this.options.xhtml ? "<hr/>\n" : "<hr>\n";
    };

    Renderer.prototype.list = function(body, ordered) {
        const type = ordered ? "ol" : "ul";
        return "<" + type + ">\n" + body + "</" + type + ">\n";
    };

    Renderer.prototype.listitem = function(text) {
        return "<li>" + text + "</li>\n";
    };

    Renderer.prototype.paragraph = function(text) {
        return "<p>" + text + "</p>\n";
