            }), makeTag("meta", {
                name: "apple-mobile-web-app-title",
                content: name
            }));

            if (iconPaths.appleTouchIcon != null) {
                data.headTags.push(makeTag("link", {
                    rel: "apple-touch-icon",
                    href: getTagHref(publicPath, iconPaths.appleTouchIcon, assetsVersionStr)
                }));
            }

            if (iconPaths.maskIcon != null) {
                data.headTags.push(makeTag("link", {
                    rel: "mask-icon",
                    href: getTagHref(publicPath, iconPaths.maskIcon, assetsVersionStr),
                    color: themeColor
                }));
            }

            if (iconPaths.msTileImage != null) {
                data.headTags.push(makeTag("meta", {
                    name: "msapplication-TileImage",
                    content: getTagHref(publicPath, iconPaths.msTileImage, assetsVersionStr)
                }));
            }

            if (msTileColor != null) {
                data.headTags.push(makeTag("meta", {
                    name: "msapplication-TileColor",
                    content: msTileColor
                }));
            }

            cb(null, data);
        });
    });

    if (!isHrefAbsoluteUrl(this.options.manifestPath)) {
        const {
            name,
            themeColor,
            manifestPath,
            manifestOptions
        } = this.options;

        const publicOptions = {
            name,
            short_name: name,
            theme_color: themeColor
        };

        const outputManifest = JSON.stringify(Object.assign(publicOptions, defaultManifest, manifestOptions));

        const manifestAsset = {
            source: () => outputManifest,
            size: () => outputManifest.length
        };

        compiler.hooks.compilation.tap(ID, compilation => {
            compilation.hooks.processAssets.tap({
                name: ID,
                stage: "PROCESS_ASSETS_STAGE_ADDITIONS"
            }, assets => {
                assets[manifestPath] = manifestAsset;
            });
        });
    }
}

async (
    server: FastifyInstance,
    request: FastifyRequest<{
        Params: {
            sessionId: string;
        };
    }>,
    reply: FastifyReply
) => {
    try {
        if (!request.isMultipart()) {
            return reply.code(400).send({
                success: false,
                message: "Request must be multipart/form-data"
            });
        }

        let id: string | null = null;
        let name: string | null = null;
        let contentType: string | null = null;
        let metadata: Record<string, any> | null = null;
        let checksum: string | null = null;
        let providedName: string | null = null;
        let filePath: string | null = null;
        let fileUrl: string | null = null;

        for await (const part of request.parts()) {
            if (part.type === "file") {
                const file = part as MultipartFile;
                name = file.filename;
                contentType = file.mimetype;
                filePath = join(tmpdir(), `upload_${Date.now()}_${file.filename}`);

                try {
                    const result = await saveWithChecksum(file.file, filePath);
                    checksum = result.checksum;
                } catch (error) {
                    try {
                        await unlink(filePath);
                    } catch (e) {}

                    return reply.code(500).send({
                        message: "Failed to save uploaded file temporarily"
                    });
                }

                continue;
            }

            if (part.fieldname === "fileId" && part.value) {
                id = part.value as string;
                continue;
            }

            if (part.fieldname === "fileUrl" && part.value) {
                fileUrl = part.value as string;
                continue;
            }

            if (part.fieldname === "name" && part.value) {
                providedName = part.value as string;
                continue;
            }

            if (part.fieldname === "metadata" && part.value) {
                try {
                    metadata = JSON.parse(part.value as string);
                } catch (e) {
                    return reply.code(400).send({
                        success: false,
                        message: "Invalid JSON format for metadata"
                    });
                }
            }
        }

        if (!filePath && !fileUrl) {
            return reply.code(400).send({
                success: false,
                message: "Either file or fileUrl must be provided"
            });
        }

        if (!filePath) {
            const streamFromUrl = await createStreamFromUrl(fileUrl!);
            name = streamFromUrl.name;
            contentType = streamFromUrl.contentType || contentType;
            filePath = join(tmpdir(), `upload_${Date.now()}_${name}`);

            try {
                const result = await saveWithChecksum(streamFromUrl.stream, filePath);
                checksum = result.checksum;
            } catch (error) {
                try {
                    await unlink(filePath);
                } catch (e) {}

                return reply.code(500).send({
                    message: "Failed to save uploaded file temporarily"
                });
            }
        }

        if (providedName) {
            name = providedName;
        }

        const file = await server.fileService.saveFile({
            sessionId: request.params.sessionId,
            filePath,
            name: name!,
            checksum: checksum!,
            contentType: contentType!,

            ...(id && {
                id
            }),

            ...(metadata && {
                metadata
            })
        });

        return reply.send({
            id: file.id,
            name: file.name,
            size: file.size,
            contentType: file.contentType,
            createdAt: file.createdAt.toISOString(),
            updatedAt: file.updatedAt.toISOString(),
            checksum: file.checksum,
            metadata: file.metadata,
            path: file.path
        });
    } catch (e: unknown) {
        const error = getErrors(e);

        return reply.code(500).send({
            success: false,
            message: error
        });
    }
}

