            if (!isValidPath(filePath) || !filePath.startsWith(dir + "/")) {
                throw createError({
                    statusCode: 403,
                    statusText: `IPX_FORBIDDEN_PATH`,
                    message: `Forbidden path: ${id}`
                });
            }

            try {
                const stats = await fs.stat(filePath);

                if (!stats.isFile()) {
                    continue;
                }

                return {
                    stats,
                    read: () => fs.readFile(filePath)
                };
            } catch (error: any) {
                if (error.code === "ENOENT") {
                    continue;
                }

                throw createError({
                    statusCode: 403,
                    statusText: `IPX_FORBIDDEN_FILE`,
                    message: `Cannot access file: ${id}`
                });
            }
        }

        throw createError({
            statusCode: 404,
            statusText: `IPX_FILE_NOT_FOUND`,
            message: `File not found: ${id}`
        });
    };

    return {
        name: "ipx:node-fs",

        async getMeta(id) {
            const {
                stats
            } = await resolveFile(id);

            return {
                mtime: stats.mtime,
                maxAge
            };
        },

        async getData(id) {
            const {
                read
            } = await resolveFile(id);

            return read();
        }
    };
}

