                    name: data.name,
                    config: _config
                };

                return;
            }

            openToolPageWithMcpServerJson({
                name: data.name,
                config: _config
            });
        });

        return () => {
            unregistLogin();
            unregistLogout();
            unlistenRefresh();
            unlistenMcpInstall();
        };
    }, []);

