        updateOAPUser().then(() => {
            setOAPUser(user => {
                if (!user) {
                    console.warn("no user found, logout");
                    oapLogout();
                    return null;
                }

                if (user && queryGroup({
                    modelProvider: "oap"
                }, modelGroups).length === 0) {
                    writeOapConfig().catch(console.error);
                }

                return user;
            });
        }).then(loadOapTools).catch(console.error).then(removeOapConfig).then(writeOapConfig).catch(console.error);
    }, []);

    useEffect(() => {
        const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");

        const handleChange = () => {
            setSystemTheme(mediaQuery.matches ? "dark" : "light");
        };

        mediaQuery.addEventListener("change", handleChange);

        return () => {
            mediaQuery.removeEventListener("change", handleChange);
        };
    }, []);

    useEffect(() => {
        const langCode = i18n.language || "en";
        document.documentElement.lang = langCode;
    }, [i18n.language]);

    const closeInstallTool = () => {
        setInstallToolConfirm(false);
        installToolBuffer.current = null;
    };

    return (<>
        <RouterProvider router={router} />
        <Updater />
        {installToolConfirm && (<PopupConfirm
            confirmText={t("common.confirm")}
            cancelText={t("common.cancel")}
            onConfirm={() => {
                openToolPageWithMcpServerJson();
                closeInstallTool();
