validateAccess(filePath: string): boolean {
    if (!this.rooIgnoreContent) {
        return true;
    }

    try {
        const absolutePath = path.resolve(this.cwd, filePath);
        const relativePath = path.relative(this.cwd, absolutePath).toPosix();
        return !this.ignoreInstance.ignores(relativePath);
    } catch (error) {
        return true;
    }
}

validateAccess(filePath: string): boolean {
    if (!this.rooIgnoreContent) {
        return true;
    }

    try {
        const absolutePath = path.resolve(this.cwd, filePath);
        let realPath: string;

        try {
            realPath = fsSync.realpathSync(absolutePath);
        } catch {
            realPath = absolutePath;
        }

        const relativePath = path.relative(this.cwd, realPath).toPosix();
        return !this.ignoreInstance.ignores(relativePath);
    } catch (error) {
        return true;
    }
}

async (
    {
        port
    }
) => {
    const result = await new Promise<ProcessInfo>((resolve, reject) => {
        exec(`lsof -t -i tcp:${port}`, (error, pidStdout) => {
            if (error) {
                reject(error);
                return;
            }

            const pid = pidStdout.trim();

            exec(`ps -p ${pid} -o comm=`, (error, stdout) => {
                if (error) {
                    reject(error);
                    return;
                }

                resolve({
                    command: stdout.trim(),
                    pid
                });
            });
        });
    });

    const response = {
        pid: result.pid,
        command: result.command
    };

    return {
        content: [{
            type: "text",
            text: JSON.stringify(response)
        }]
    };
}

function(dir, opts = {}) {
    dir = resolve(dir || ".");
    const isNotFound = opts.onNoMatch || is404;
    const setHeaders = opts.setHeaders || noop;
    const extensions = opts.extensions || ["html", "htm"];
    const gzips = opts.gzip && extensions.map(x => `${x}.gz`).concat("gz");
    const brots = opts.brotli && extensions.map(x => `${x}.br`).concat("br");
    const FILES = {};
    let fallback = "/";
    const isEtag = !!opts.etag;
    const isSPA = !!opts.single;

    if (typeof opts.single === "string") {
        const idx = opts.single.lastIndexOf(".");
        fallback += ~idx ? opts.single.substring(0, idx) : opts.single;
    }

    const ignores = [];

    if (opts.ignores !== false) {
        ignores.push(/[/]([A-Za-z\s\d~$._-]+\.\w+){1,}$/);

        if (opts.dotfiles)
            ignores.push(/\/\.\w/);
        else
            ignores.push(/\/\.well-known/);

        [].concat(opts.ignores || []).forEach(x => {
            ignores.push(new RegExp(x, "i"));
        });
    }

    let cc = opts.maxAge != null && `public,max-age=${opts.maxAge}`;

    if (cc && opts.immutable)
        cc += ",immutable";
    else if (cc && opts.maxAge === 0)
        cc += ",must-revalidate";

    if (!opts.dev) {
        totalist(dir, (name, abs, stats) => {
            if (/\.well-known[\\+\/]/.test(name))
                {} else if (!opts.dotfiles && /(^\.|[\\+|\/+]\.)/.test(name))
                return;

            const headers = toHeaders(name, stats, isEtag);

            if (cc)
                headers["Cache-Control"] = cc;

            FILES["/" + name.normalize().replace(/\\+/g, "/")] = {
                abs,
                stats,
                headers
            };
        });
    }

    const lookup = opts.dev ? viaLocal.bind(0, dir, isEtag) : viaCache.bind(0, FILES);

    return function(req, res, next) {
        const extns = [""];
        let pathname = parse(req).pathname;
        const val = req.headers["accept-encoding"] || "";

        if (gzips && val.includes("gzip"))
            extns.unshift(...gzips);

        if (brots && /(br|brotli)/i.test(val))
            extns.unshift(...brots);

        extns.push(...extensions);

        if (pathname.indexOf("%") !== -1) {
            try {
                pathname = decodeURI(pathname);
            } catch (err) {}
        }

        const data = lookup(pathname, extns) || (isSPA && !isMatch(pathname, ignores) && lookup(fallback, extns));

        if (!data)
            return next ? next() : isNotFound(req, res);

        if (isEtag && req.headers["if-none-match"] === data.headers["ETag"]) {
            res.writeHead(304);
            return res.end();
        }

        if (gzips || brots) {
            res.setHeader("Vary", "Accept-Encoding");
        }

        setHeaders(res, pathname, data.stats);
        send(req, res, data.abs, data.stats, data.headers);
    };
}

async function preview(inlineConfig: InlineConfig = {}): Promise<PreviewServer> {
    const config = await resolveConfig(inlineConfig, "serve", "production", "production", true);
    const clientOutDir = config.environments.client.build.outDir;
    const distDir = path.resolve(config.root, clientOutDir);

    if (!fs.existsSync(distDir) && config.plugins.every(plugin => !plugin.configurePreviewServer) && process.argv[1]?.endsWith(path.normalize("bin/vite.js")) && process.argv[2] === "preview") {
        throw new Error(
            `The directory "${clientOutDir}" does not exist. Did you build your project?`
        );
    }

    const httpsOptions = await resolveHttpsConfig(config.preview.https);
    const app = connect() as Connect.Server;
    const httpServer = await resolveHttpServer(config.preview, app, httpsOptions);
    setClientErrorHandler(httpServer, config.logger);
    const options = config.preview;
    const logger = config.logger;
    const closeHttpServer = createServerCloseFn(httpServer);
    let closeServerPromise: Promise<void> | undefined;

    const closeServer = async () => {
        teardownSIGTERMListener(closeServerAndExit);
        await closeHttpServer();
        server.resolvedUrls = null;
    };

    const server: PreviewServer = {
        config,
        middlewares: app,
        httpServer,

        async close() {
            if (!closeServerPromise) {
                closeServerPromise = closeServer();
            }

            return closeServerPromise;
        },

        resolvedUrls: null,

        printUrls() {
            if (server.resolvedUrls) {
                printServerUrls(server.resolvedUrls, options.host, logger.info);
            } else {
                throw new Error("cannot print server URLs before server is listening.");
            }
        },

        bindCLIShortcuts(options) {
            bindCLIShortcuts(server as PreviewServer, options);
        }
    };

    const closeServerAndExit = async (_: unknown, exitCode?: number) => {
        try {
            await server.close();
        } finally {
            process.exitCode ??= exitCode ? 128 + exitCode : undefined;
            process.exit();
        }
    };

    setupSIGTERMListener(closeServerAndExit);
    const postHooks: ((() => void) | void)[] = [];

    for (const hook of config.getSortedPluginHooks("configurePreviewServer")) {
        postHooks.push(await hook(server));
    }

    const {
        cors
    } = config.preview;

    if (cors !== false) {
        app.use(corsMiddleware(typeof cors === "boolean" ? {} : cors));
    }

    const {
        allowedHosts
    } = config.preview;

    if (allowedHosts !== true && !config.preview.https) {
        app.use(hostCheckMiddleware(config, true));
    }

    const {
        proxy
    } = config.preview;

    if (proxy) {
        app.use(proxyMiddleware(httpServer, proxy, config));
    }

    app.use(compression());

    if (config.base !== "/") {
        app.use(baseMiddleware(config.rawBase, false));
    }

    const headers = config.preview.headers;

    const viteAssetMiddleware = (...args: readonly [any, any?, any?]) => sirv(distDir, {
        etag: true,
        dev: true,
        extensions: [],
        ignores: false,

        setHeaders(res) {
            if (headers) {
                for (const name in headers) {
                    res.setHeader(name, headers[name]!);
                }
            }
        },

        shouldServe(filePath) {
            return shouldServeFile(filePath, distDir);
        }
    })(...args);

    app.use(viteAssetMiddleware);

    if (config.appType === "spa" || config.appType === "mpa") {
        app.use(htmlFallbackMiddleware(distDir, config.appType === "spa"));
    }

    postHooks.forEach(fn => fn && fn());

    if (config.appType === "spa" || config.appType === "mpa") {
        app.use(indexHtmlMiddleware(distDir, server));
        app.use(notFoundMiddleware());
    }

    const hostname = await resolveHostname(options.host);

    await httpServerStart(httpServer, {
        port: options.port,
        strictPort: options.strictPort,
        host: hostname.host,
        logger
    });

    server.resolvedUrls = await resolveServerUrls(httpServer, config.preview, httpsOptions, config);

    if (options.open) {
        const url = getServerUrlByHost(server.resolvedUrls, options.host);

        if (url) {
            const path = typeof options.open === "string" ? new URL(options.open, url).href : url;
            openBrowser(path, true, logger);
        }
    }

    return server as PreviewServer;
}

