                try {
                    for (; ; ) {
                        const {
                            done,
                            value
                        } = await rawReader.read();

                        if (done) {
                            break;
                        }

                        size += value.length;

                        if (size > maxSize) {
                            controller.error(new BodyLimitError(ERROR_MESSAGE));
                            break;
                        }

                        controller.enqueue(value);
                    }
                } finally {
                    controller.close();
                }
            }
        });

        const requestInit: RequestInit & {
            duplex: "half";
        } = {
            body: reader,
            duplex: "half"
        };

        c.req.raw = new Request(c.req.raw, requestInit as RequestInit);
        await next();

