        appUrl,
        originalUrl
    } = useAtomValue(appUrlAtom);

    const setAppOutput = useSetAtom(appOutputAtom);
    const [reloadKey, setReloadKey] = useState(0);
    const [errorMessage, setErrorMessage] = useAtom(previewErrorMessageAtom);
    const selectedChatId = useAtomValue(selectedChatIdAtom);

    const {
        streamMessage
    } = useStreamChat();

    const {
        routes: availableRoutes
    } = useParseRouter(selectedAppId);

    const {
        restartApp
    } = useRunApp();

    const [isComponentSelectorInitialized, setIsComponentSelectorInitialized] = useState(false);
    const [canGoBack, setCanGoBack] = useState(false);
    const [canGoForward, setCanGoForward] = useState(false);
    const [navigationHistory, setNavigationHistory] = useState<string[]>([]);
    const [currentHistoryPosition, setCurrentHistoryPosition] = useState(0);
    const [selectedComponentPreview, setSelectedComponentPreview] = useAtom(selectedComponentPreviewAtom);
    const iframeRef = useRef<HTMLIFrameElement>(null);
    const [isPicking, setIsPicking] = useState(false);

    useEffect(() => {
        if (!selectedComponentPreview) {
            if (iframeRef.current?.contentWindow) {
                iframeRef.current.contentWindow.postMessage({
                    type: "deactivate-dyad-component-selector"
                }, "*");
            }

            setIsPicking(false);
        }
    }, [selectedComponentPreview]);

    useEffect(() => {
        const handleMessage = (event: MessageEvent) => {
            if (event.source !== iframeRef.current?.contentWindow) {
                return;
            }

            if (event.data?.type === "dyad-component-selector-initialized") {
                setIsComponentSelectorInitialized(true);
                return;
            }

            if (event.data?.type === "dyad-component-selected") {
                console.log("Component picked:", event.data);
                setSelectedComponentPreview(parseComponentSelection(event.data));
                setIsPicking(false);
                return;
            }

            const {
                type,
                payload
            } = event.data as {
                type: "window-error" | "unhandled-rejection" | "iframe-sourcemapped-error" | "build-error-report" | "pushState" | "replaceState";
                payload?: {
                    message?: string;
                    stack?: string;
                    reason?: string;
                    newUrl?: string;
                    file?: string;
                    frame?: string;
                };
            };

            if (type === "window-error" || type === "unhandled-rejection" || type === "iframe-sourcemapped-error") {
                const stack = type === "iframe-sourcemapped-error" ? payload?.stack?.split("\n").slice(0, 1).join("\n") : payload?.stack;
                const errorMessage = `Error ${payload?.message || payload?.reason}\nStack trace: ${stack}`;
                console.error("Iframe error:", errorMessage);
                setErrorMessage(errorMessage);

                setAppOutput(prev => [...prev, {
                    message: `Iframe error: ${errorMessage}`,
                    type: "client-error",
                    appId: selectedAppId!,
                    timestamp: Date.now()
                }]);
            } else if (type === "build-error-report") {
                console.debug(`Build error report: ${payload}`);
                const errorMessage = `${payload?.message} from file ${payload?.file}.\n\nSource code:\n${payload?.frame}`;
                setErrorMessage(errorMessage);

                setAppOutput(prev => [...prev, {
                    message: `Build error report: ${JSON.stringify(payload)}`,
                    type: "client-error",
                    appId: selectedAppId!,
                    timestamp: Date.now()
                }]);
            } else if (type === "pushState" || type === "replaceState") {
                console.debug(`Navigation event: ${type}`, payload);

                if (type === "pushState" && payload?.newUrl) {
                    const newHistory = [...navigationHistory.slice(0, currentHistoryPosition + 1), payload.newUrl];
                    setNavigationHistory(newHistory);
                    setCurrentHistoryPosition(newHistory.length - 1);
                } else if (type === "replaceState" && payload?.newUrl) {
                    const newHistory = [...navigationHistory];
                    newHistory[currentHistoryPosition] = payload.newUrl;
                    setNavigationHistory(newHistory);
                }
            }
        };

        window.addEventListener("message", handleMessage);
        return () => window.removeEventListener("message", handleMessage);
    }, [
        navigationHistory,
        currentHistoryPosition,
        selectedAppId,
        errorMessage,
        setErrorMessage,
        setIsComponentSelectorInitialized,
        setSelectedComponentPreview
    ]);

    useEffect(() => {
        setCanGoBack(currentHistoryPosition > 0);
        setCanGoForward(currentHistoryPosition < navigationHistory.length - 1);
    }, [navigationHistory, currentHistoryPosition]);

    useEffect(() => {
        if (appUrl) {
            setNavigationHistory([appUrl]);
            setCurrentHistoryPosition(0);
            setCanGoBack(false);
            setCanGoForward(false);
        }
    }, [appUrl]);

    const handleActivateComponentSelector = () => {
        if (iframeRef.current?.contentWindow) {
            const newIsPicking = !isPicking;
            setIsPicking(newIsPicking);

            iframeRef.current.contentWindow.postMessage({
                type: newIsPicking ? "activate-dyad-component-selector" : "deactivate-dyad-component-selector"
            }, "*");
        }
    };

    const handleNavigateBack = () => {
        if (canGoBack && iframeRef.current?.contentWindow) {
            iframeRef.current.contentWindow.postMessage({
                type: "navigate",

                payload: {
                    direction: "backward"
                }
            }, "*");

            setCurrentHistoryPosition(prev => prev - 1);
            setCanGoBack(currentHistoryPosition - 1 > 0);
            setCanGoForward(true);
        }
    };

    const handleNavigateForward = () => {
        if (canGoForward && iframeRef.current?.contentWindow) {
            iframeRef.current.contentWindow.postMessage({
                type: "navigate",

                payload: {
                    direction: "forward"
                }
            }, "*");

            setCurrentHistoryPosition(prev => prev + 1);
            setCanGoBack(true);
            setCanGoForward(currentHistoryPosition + 1 < navigationHistory.length - 1);
        }
    };

    const handleReload = () => {
        setReloadKey(prevKey => prevKey + 1);
        setErrorMessage(undefined);
        console.debug("Reloading iframe preview for app", selectedAppId);
    };

    const navigateToRoute = (path: string) => {
        if (iframeRef.current?.contentWindow && appUrl) {
            const baseUrl = new URL(appUrl).origin;
            const newUrl = `${baseUrl}${path}`;
            iframeRef.current.contentWindow.location.href = newUrl;
            const newHistory = [...navigationHistory.slice(0, currentHistoryPosition + 1), newUrl];
            setNavigationHistory(newHistory);
            setCurrentHistoryPosition(newHistory.length - 1);
            setCanGoBack(true);
            setCanGoForward(false);
        }
    };

    if (loading) {
        return (
            (<div className="flex flex-col h-full relative">
                <div
                    className="absolute inset-0 flex flex-col items-center justify-center space-y-4 bg-gray-50 dark:bg-gray-950">
                    <div className="relative w-5 h-5 animate-spin">
                        <div
                            className="absolute top-0 left-1/2 transform -translate-x-1/2 w-2 h-2 bg-primary rounded-full"></div>
                        <div
                            className="absolute bottom-0 left-0 w-2 h-2 bg-primary rounded-full opacity-80"></div>
                        <div
                            className="absolute bottom-0 right-0 w-2 h-2 bg-primary rounded-full opacity-60"></div>
                    </div>
                    <p className="text-gray-600 dark:text-gray-300">Preparing app preview...</p>
                </div>
            </div>)
        );
    }

    if (selectedAppId === null) {
        return <div className="p-4 text-gray-500 dark:text-gray-400">Select an app to see the preview.</div>;
    }

    const onRestart = () => {
        restartApp();
    };

    return (
        (<div className="flex flex-col h-full">
            {}
            <div className="flex items-center p-2 border-b space-x-2 ">
                {}
                <div className="flex space-x-1">
                    <TooltipProvider>
                        <Tooltip>
                            <TooltipTrigger asChild>
                                <button
                                    onClick={handleActivateComponentSelector}
                                    className={`p-1 rounded transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed ${isPicking ? "bg-purple-500 text-white hover:bg-purple-600 dark:bg-purple-600 dark:hover:bg-purple-700" : " text-purple-700 hover:bg-purple-200  dark:text-purple-300 dark:hover:bg-purple-900"}`}
                                    disabled={loading || !selectedAppId || !isComponentSelectorInitialized}
                                    data-testid="preview-pick-element-button">
                                    <MousePointerClick size={16} />
                                </button>
                            </TooltipTrigger>
                            <TooltipContent>
                                <p>{isPicking ? "Deactivate component selector" : "Select component"}</p>
