                        <DropdownMenuContent className="w-full">
                            {availableRoutes.length > 0 ? (availableRoutes.map(route => (<DropdownMenuItem
                                key={route.path}
                                onClick={() => navigateToRoute(route.path)}
                                className="flex justify-between">
                                <span>{route.label}</span>
                                <span className="text-gray-500 dark:text-gray-400 text-xs">{route.path}</span>
                            </DropdownMenuItem>))) : (<DropdownMenuItem disabled>Loading routes...</DropdownMenuItem>)}
                        </DropdownMenuContent>
                    </DropdownMenu>
                </div>
                {}
                <div className="flex space-x-1">
                    <button
                        onClick={onRestart}
                        className="flex items-center space-x-1 px-3 py-1 rounded-md text-sm hover:bg-[var(--background-darkest)] transition-colors"
                        title="Restart App">
                        <Power size={16} />
                        <span>Restart</span>
