                            if (originalUrl) {
                                IpcClient.getInstance().openExternalUrl(originalUrl);
                            }
                        }}
                        className="p-1 rounded hover:bg-gray-200 dark:hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed dark:text-gray-300">
                        <ExternalLink size={16} />
                    </button>
                </div>
            </div>
            <div className="relative flex-grow ">
                <ErrorBanner
                    error={errorMessage}
                    onDismiss={() => setErrorMessage(undefined)}
                    onAIFix={() => {
                        if (selectedChatId) {
                            streamMessage({
                                prompt: `Fix error: ${errorMessage}`,
                                chatId: selectedChatId
                            });
                        }
                    }} />
                {!appUrl ? (<div
                    className="absolute inset-0 flex flex-col items-center justify-center space-y-4 bg-gray-50 dark:bg-gray-950">
                    <Loader2 className="w-8 h-8 animate-spin text-gray-400 dark:text-gray-500" />
                    <p className="text-gray-600 dark:text-gray-300">Starting your app server...</p>
                </div>) : (<iframe
                    data-testid="preview-iframe-element"
                    onLoad={() => {
                        setErrorMessage(undefined);
                    }}
                    ref={iframeRef}
                    key={reloadKey}
                    title={`Preview for App ${selectedAppId}`}
                    className="w-full h-full border-none bg-white dark:bg-gray-950"
                    src={appUrl}
                    allow="clipboard-read; clipboard-write; fullscreen; microphone; camera; display-capture; geolocation; autoplay; picture-in-picture" />)}
            </div>
        </div>)
    );
}

