public async redirectToAuthorization(authorizationUrl: URL): Promise<void> {
    const url = authorizationUrl.toString();

    if (!url.startsWith("http://") && !url.startsWith("https://")) {
        throw new Error("Invalid authorization url URL");
    }

    await open(url);
}

async uploadFile(file: any): Promise<{
    filename: string;
}> {
    try {
        const filePath = `${tmpdir()}/${file.originalName}`;
        await writeFile(filePath, file.buffer);
        const form = new FormData();
        form.append("token", this.configService.get("CDN_ACCESS_TOKEN"));
        form.append("file", createReadStream(filePath));

        const {
            data
        } = await this.httpService.axiosRef.post("file", form, {
            headers: {
                "Content-Type": "multipart/form-data"
            }
        });

        await unlink(filePath);
        return data;
    } catch (error) {
        console.error(error);
        throw new InternalServerErrorException("Failed to upload extension to the CDN.");
    }
}

