        });

        return dup;
    }

    if (typeof value.__op === "string") {
        const {
            opFromJSON
        } = CoreManager.getParseOp();

        return opFromJSON(value);
    }

    const ParseObject = CoreManager.getParseObject();

    if (value.__type === "Pointer" && value.className) {
        return ParseObject.fromJSON(value);
    }

    if (value.__type === "Object" && value.className) {
        return ParseObject.fromJSON(value);
    }

    if (value.__type === "Relation") {
        const relation = new ParseRelation(null, null);
        relation.targetClassName = value.className;
        return relation;
    }

    if (value.__type === "Date") {
        return new Date(value.iso);
    }

    if (value.__type === "File") {
        return ParseFile.fromJSON(value);
    }

    if (value.__type === "GeoPoint") {
        return new ParseGeoPoint({
            latitude: value.latitude,
            longitude: value.longitude
        });
    }

    if (value.__type === "Polygon") {
        return new ParsePolygon(value.coordinates);
    }

    const copy = {};

    for (const k in value) {
        copy[k] = decode(value[k]);
    }

    return copy;
}

function encode(
    value: any,
    disallowObjects: boolean,
    forcePointers: boolean,
    seen: any[],
    offline: boolean
): any {
    const ParseObject = CoreManager.getParseObject();

    if (value instanceof ParseObject) {
        if (disallowObjects) {
            throw new Error("Parse Objects not allowed here");
        }

        const seenEntry = value.id ? value.className + ":" + value.id : value;

        if (forcePointers || !seen || seen.indexOf(seenEntry) > -1 || value.dirty() || Object.keys(value._getServerData()).length < 1) {
            if (offline && value._getId().startsWith("local")) {
                return value.toOfflinePointer();
            }

            return value.toPointer();
        }

        seen = seen.concat(seenEntry);
        return value._toFullJSON(seen, offline);
    }

    const {
        Op
    } = CoreManager.getParseOp();

    if (value instanceof Op || value instanceof ParseACL || value instanceof ParseGeoPoint || value instanceof ParsePolygon || value instanceof ParseRelation) {
        return value.toJSON();
    }

    if (value instanceof ParseFile) {
        if (!value.url()) {
            throw new Error("Tried to encode an unsaved file.");
        }

        return value.toJSON();
    }

    if (Object.prototype.toString.call(value) === "[object Date]") {
        if (isNaN(value)) {
            throw new Error("Tried to encode an invalid date.");
        }

        return {
            __type: "Date",
            iso: (value as Date).toJSON()
        };
    }

    if (Object.prototype.toString.call(value) === "[object RegExp]" && typeof value.source === "string") {
        return value.source;
    }

    if (Array.isArray(value)) {
        return value.map(v => {
            return encode(v, disallowObjects, forcePointers, seen, offline);
        });
    }

    if (value && typeof value === "object") {
        const output = {};

        for (const k in value) {
            output[k] = encode(value[k], disallowObjects, forcePointers, seen, offline);
        }

        return output;
    }

    return value;
}

