function isFileLoadingAllowed(config: ResolvedConfig, filePath: string): boolean {
    const {
        fs
    } = config.server;

    if (!fs.strict)
        return true;

    if (config.fsDenyGlob(filePath))
        return false;

    if (config.safeModulePaths.has(filePath))
        return true;

    if (fs.allow.some(uri => isFileInTargetPath(uri, filePath)))
        return true;

    return false;
}

