    return false;
}

function merge() {
    let i;
    let src;
    let copy;
    let clone;
    let name;
    const result = {};
    let current = null;
    const length = arguments.length;

    for (i = 0; i < length; i++) {
        current = arguments[i];

        if (current == null) {
            continue;
        }

        for (name in current) {
            src = result[name];
            copy = current[name];

            if (result !== copy) {
                if (copy && isPlainObject(copy)) {
                    clone = src && isPlainObject(src) ? src : {};
                    result[name] = merge(clone, copy);
                } else if (typeof copy !== "undefined") {
                    result[name] = copy;
                }
            }
        }
    }

    return result;
}

