async function openURLMiddleware(
    req: IncomingMessage & {
        body?: object;
    },
    res: ServerResponse,
    next: (err?: Error) => void
) {
    if (req.method === "POST") {
        if (req.body == null) {
            res.writeHead(400);
            res.end("Missing request body");
            return;
        }

        const {
            url
        } = req.body as {
            url: string;
        };

        await open(url);
        res.writeHead(200);
        res.end();
    }

    next();
}

async function openURLMiddleware(
    req: IncomingMessage & {
        body?: object;
    },
    res: ServerResponse,
    next: (err?: Error) => void
) {
    if (req.method === "POST") {
        if (req.body == null) {
            res.writeHead(400);
            res.end("Missing request body");
            return;
        }

        const {
            url
        } = req.body as {
            url: string;
        };

        try {
            const parsedUrl = new URL(url);

            if (parsedUrl.protocol !== "http:" && parsedUrl.protocol !== "https:") {
                res.writeHead(400);
                res.end("Invalid URL protocol");
                return;
            }
        } catch (error) {
            res.writeHead(400);
            res.end("Invalid URL format");
            return;
        }

        await open(url);
        res.writeHead(200);
        res.end();
    }

    next();
}

function openBrowser(url) {
    const command = process.platform === "darwin" ? "open" : process.platform === "win32" ? "start" : "xdg-open";

    exec(`${command} "${url}"`, error => {
        if (error) {
            console.error("❌ Failed to open browser:", error.message);
            console.error("📋 Please manually open this URL in your browser:");
            console.error(url);
        } else {
            console.error("🌐 Browser opened for Evernote authorization");
        }
    });
}

function openBrowser(url) {
    let command;
    let args;

    if (process.platform === "darwin") {
        command = "open";
        args = [url];
    } else if (process.platform === "win32") {
        command = "cmd";
        args = ["/c", "start", "", url];
    } else {
        command = "xdg-open";
        args = [url];
    }

    const child = spawn(command, args, {
        stdio: "ignore",
        detached: true
    });

    child.on("error", error => {
        console.error("❌ Failed to open browser:", error.message);
        console.error("📋 Please manually open this URL in your browser:");
        console.error(url);
    });

    child.unref();
    console.error("🌐 Browser opened for Evernote authorization");
}
